INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Takut Salah Ngomong Saat Bertemu Orang Italia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak pemula Indonesia ingin bisa bahasa Italia karena musik, kuliner, dan sepak bolanya, tetapi urung belajar karena takut salah pengucapan atau dianggap tidak sopan. Padahal, orang Italia justru sangat menghargai usaha orang asing yang mencoba berbahasa mereka — satu sapaan yang benar sudah membuka pintu percakapan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Sapaan Adalah Kunci Budaya Italia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Di Italia, menyapa bukan sekadar formalitas. Mengucapkan 'buongiorno' saat masuk toko atau 'arrivederci' saat pergi adalah tanda hormat. Salah memilih sapaan (misalnya memakai 'ciao' ke orang yang lebih tua dan belum akrab) bisa dianggap kurang sopan. Kabar baiknya: pengucapan bahasa Italia hampir selalu dibaca apa adanya, jauh lebih mudah daripada bahasa Inggris.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Aplikasi kamus Italia-Indonesia (misalnya Reverso atau WordReference)$$, $$Aplikasi pelafalan seperti Forvo untuk mendengar penutur asli$$, $$Buku catatan kecil atau aplikasi flashcard (Anki)$$, $$Waktu latihan 15 menit sehari$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Kuasai 10 Sapaan Dasar dalam 30 Hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Buongiorno (bwon-JOR-no) — selamat pagi/siang, dipakai sampai sore$$, $$Buonasera (bwo-na-SE-ra) — selamat sore/malam, dipakai mulai sekitar pukul 17.00$$, $$Buonanotte (bwo-na-NOT-te) — selamat tidur, hanya untuk perpisahan malam$$, $$Ciao (CHAO) — halo/dadah santai, hanya untuk teman dan orang sebaya$$, $$Come stai? (KO-me STAI) — apa kabar? (informal)$$, $$Come sta? (KO-me STA) — apa kabar? (formal/sopan)$$, $$Mi chiamo ... (mi KYA-mo) — nama saya ...$$, $$Piacere (pya-CHE-re) — senang bertemu denganmu$$, $$Grazie (GRA-tsye) — terima kasih; prego (PRE-go) — sama-sama/silakan$$, $$Arrivederci (ar-ri-ve-DER-chi) — sampai jumpa (lebih sopan daripada ciao)$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Kesalahan Umum Pemula$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Memakai 'ciao' ke orang tua, atasan, atau orang baru — gunakan buongiorno/buonasera dulu$$, $$Menjawab telepon dengan 'pronto' adalah benar, tetapi jangan dipakai untuk menyapa langsung$$, $$Mengucapkan 'grazie' tanpa senyuman — orang Italia membaca bahasa tubuh$$, $$Menyebut nama dengan 'signore/signora' tanpa tahu konteks — untuk pemula cukup nama + senyuman$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Langkah Berikutnya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Mampu mengucapkan 10 sapaan dengan pengucapan yang bisa dipahami penutur asli$$, $$Tahu kapan memakai ciao vs buongiorno/buonasera$$, $$Bisa memperkenalkan nama sendiri: 'Ciao, mi chiamo ...'$$, $$Setelah 30 hari latihan konsisten, tantang dirimu: sapa satu penutur Italia (misalnya di komunitas bahasa atau media sosial) dan perkenalkan diri. Langkah berikutnya: pelajari angka 1–20 dan cara memesan makanan di restoran.$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Panik Saat Hidung Tiba-tiba Berdarah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Mimisan bisa muncul tiba-tiba — saat cuaca panas, setelah bersin keras, atau bahkan tanpa sebab jelas. Reaksi paling umum adalah panik dan mendongakkan kepala ke belakang, padahal itu justru membuat darah mengalir ke tenggorokan dan bisa memicu mual. Artikel ini memberi langkah yang benar, aman, dan bisa dilakukan siapa pun di rumah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Mengapa Mimisan Terjadi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Mimisan (epistaksis) terjadi ketika pembuluh darah kecil di dinding dalam hidung pecah. Penyebab umum: udara kering, mengorek hidung, bersin/ batuk keras, pilek, alergi, atau benturan. Sebagian besar mimisan berasal dari bagian depan hidung dan berhenti sendiri dalam 10–20 menit dengan penanganan yang benar. Catatan: artikel ini berisi informasi umum, bukan pengganti nasihat medis profesional.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Tisu atau kain bersih$$, $$Kompres dingin (es dibungkus kain)$$, $$Jam atau timer untuk menghitung waktu$$, $$Air bersih untuk membersihkan$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Hentikan Mimisan dalam 15 Menit$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Duduk tegak dan condongkan badan sedikit ke depan — jangan berbaring atau mendongak$$, $$Jepit bagian lunak hidung (cuping, di bawah tulang hidung) dengan ibu jari dan telunjuk$$, $$Tekan terus tanpa melepas selama 10–15 menit penuh — gunakan timer$$, $$Bernapaslah lewat mulut selama menekan$$, $$Setelah berhenti, jangan mengorek, membuang ingus keras, atau membungkuk selama beberapa jam$$, $$Tempelkan kompres dingin di pangkal hidung untuk membantu menyempitkan pembuluh$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Kesalahan yang Harus Dihindari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Mendongakkan kepala — darah masuk tenggorokan, bisa mual dan muntah$$, $$Melepas jepitan terlalu cepat untuk 'mengecek' — lakukan tanpa jeda 10–15 menit$$, $$Memasukkan tisu/kapas ke dalam lubang hidung — bisa merusak bekuan darah yang terbentuk$$, $$Mengonsumsi aspirin atau obat pengencer darah tanpa anjuran dokter saat mimisan sering terjadi$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Kapan ke Dokter$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Darah berhenti dalam 20 menit — penanganan berhasil$$, $$Segera ke dokter/IGD jika: darah tidak berhenti setelah 20–30 menit, mimisan sangat sering kambuh, darah mengalir deras ke tenggorokan, atau terjadi setelah cedera kepala$$, $$Konsultasikan ke dokter jika mengonsumsi obat pengencer darah atau memiliki gangguan pembekuan$$, $$Pencegahan: jaga kelembapan udara ruangan, jangan mengorek hidung, dan tangani pilek/alergi dengan baik. Jika mimisan menjadi kejadian rutin, catat frekuensi dan pemicunya lalu konsultasikan ke dokter.$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Air Terjun Raksasa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Air terjun tertinggi di dunia bukan sekadar pemandangan indah — ia adalah laboratorium geologi raksasa. Ketinggian totalnya bisa melebihi gedung pencakar langit tertinggi, dan airnya sering berubah menjadi kabut sebelum mencapai dasar.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$1. Angel Falls — 979 Meter (Venezuela)$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Air Terjun Angel di Taman Nasional Canaima, Venezuela, memegang rekor dunia dengan ketinggian total 979 meter dan terjunan bebas terpanjang 807 meter. Airnya jatuh dari tebing Auyan-tepui, gunung meja berumur miliaran tahun. Saking tingginya, air sering menguap menjadi kabut sebelum menyentuh tanah. Nama lokalnya Kerepakupai Merú, yang berarti 'air terjun dari tempat terdalam'.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$2. Tugela Falls dan 3. Tres Hermanas (Afrika Selatan & Peru)$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Tugela Falls di Pegunungan Drakensberg, Afrika Selatan, diklaim setinggi 983 meter dalam lima tingkat terjunan — angka yang sempat menantangnya sebagai yang tertinggi dunia. Perdebatan pengukuran antara Angel dan Tugela menunjukkan betapa sulitnya mengukur air terjun bertingkat secara presisi. Sementara itu, Tres Hermanas ('Tiga Bersaudara') di Peru jatuh setinggi 914 meter dalam tiga tingkat di tengah hutan Amazon yang terpencil — contoh air terjun yang masih liar dan hampir tak tersentuh.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Bagaimana Air Terjun Setinggi Itu Terbentuk$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Air terjun raksasa umumnya terbentuk di tebing curam dataran tinggi (tepui atau escarpment) tempat sungai bertemu lapisan batuan keras di atas batuan lunak. Erosi menggerus batuan lunak di bawahnya, menciptakan jurang vertikal yang terus mundur ke hulu selama ribuan tahun. Ketinggian Angel Falls hampir tiga kali Menara Eiffel, dan airnya sering menguap menjadi kabut sebelum menyentuh tanah — menciptakan ekosistem mikro lumut dan tumbuhan khusus di zona percikannya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Air Terjun Tinggi di Indonesia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Air Terjun Sipiso-piso, Sumatera Utara — sekitar 120 meter, salah satu tertinggi di Indonesia$$, $$Air Terjun Madakaripura, Jawa Timur — sekitar 200 meter termasuk tirai airnya$$, $$Air Terjun Nokan Nayan, Kalimantan Barat — sekitar 50 meter dengan lebar mengesankan$$, $$Indonesia kaya air terjun karena topografi vulkanik dan curah hujan tinggi$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Drone$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Drone (UAV — Unmanned Aerial Vehicle) adalah pesawat tanpa awak yang dikendalikan dari jarak jauh atau terbang otomatis mengikuti program. Yang paling populer adalah quadcopter: empat baling-baling yang berputar berpasangan berlawanan arah agar seimbang di udara.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Cara Kerja Drone$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Empat motor mengubah kecepatan putar tiap baling-baling untuk naik, turun, maju, dan berputar. Sensor giroskop dan akselerometer menjaga kestabilan ratusan kali per detik, GPS mengunci posisi, dan kamera gimbal menstabilkan gambar. Baterai litium memberi waktu terbang tipikal 20–40 menit untuk drone konsumen.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Jenis-Jenis Drone$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Multirotor (quadcopter/hexacopter) — lincah, bisa hover, untuk foto udara dan inspeksi$$, $$Fixed-wing (sayap tetap) — terbang jauh dan lama, untuk pemetaan area luas$$, $$FPV racing drone — kecil, cepat, dikendalikan lewat kacamata video real-time$$, $$Drone industri/militer — besar, membawa sensor canggih atau muatan$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Kegunaan di Dunia Nyata$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Fotografi dan sinematografi udara$$, $$Pemetaan dan survei lahan, tambang, dan perkebunan$$, $$Pertanian presisi: menyemprot dan memantau tanaman$$, $$Penanggulangan bencana: mencari korban dan memetakan daerah terdampak$$, $$Inspeksi infrastruktur: menara, jembatan, dan panel surya$$, $$Pengiriman barang ke daerah terpencil (masih berkembang)$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Aturan dan Keamanan Terbang$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Di Indonesia, pengoperasian drone diatur antara lain oleh Kementerian Perhubungan. Prinsip umumnya: jangan terbang di dekat bandara, di atas kerumunan orang, atau di ketinggian yang membahayakan penerbangan berawak; drone dengan berat tertentu wajib registrasi. Selalu cek aturan terbaru sebelum terbang — pelanggaran bisa berujung denda dan penyitaan. Baling-baling berputar cepat bisa melukai, baterai litium bisa terbakar jika rusak, dan jangan merekam area privat tanpa izin. Ke depan, drone otonom berkecerdasan buatan akan semakin umum — tetapi fondasinya tetap sama: terbang aman dan bertanggung jawab.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$$Siswa memahami pengertian dan fungsi descriptive text$$, $$Siswa dapat mengidentifikasi struktur identification dan description$$, $$Siswa dapat menulis descriptive text sederhana tentang orang, hewan, atau benda$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Descriptive Text$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Descriptive text adalah teks yang menggambarkan seseorang, hewan, benda, atau tempat secara detail agar pembaca seolah-olah melihat atau merasakannya sendiri. Tujuannya: to describe a particular person, place, or thing.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Struktur dan Ciri Kebahasaan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Identification — mengenalkan subjek yang dideskripsikan (siapa/apa yang dibicarakan)$$, $$Description — menjelaskan ciri-ciri detail: penampilan, sifat, kebiasaan, bagian-bagiannya$$, $$Menggunakan Simple Present Tense (is, are, has, have)$$, $$Kata sifat (adjectives): beautiful, tall, friendly, fluffy$$, $$Fokus pada satu subjek khusus (my cat, Borobudur, my mother) — bukan umum$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Contoh Teks$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$My Cat, Miko. I have a pet. It is a cat. Its name is Miko. Miko has soft white fur and round green eyes. It is very playful and friendly. Every morning, Miko drinks milk and plays with a ball of yarn. I love Miko very much.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Analisis Contoh$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Identification: 'I have a pet. It is a cat. Its name is Miko.' Description: bulu putih lembut, mata hijau bulat, sifat playful dan friendly, serta kebiasaan pagi hari. Tenses yang dipakai semuanya Simple Present (is, has, drinks, plays) dengan kata sifat soft, white, round, green, playful, friendly.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$1. What is the purpose of a descriptive text? → To describe a particular person, place, or thing in detail.$$, $$2. Mention the two parts of the generic structure! → Identification and description.$$, $$3. Write three adjectives to describe your best friend! → (contoh: kind, smart, funny.)$$, $$4. Change into English: 'Kucingku memiliki ekor yang panjang.' → 'My cat has a long tail.'$$, $$Tips: gunakan pancaindra — apa yang terlihat, terdengar, tercium, terasa — agar teksmu hidup di mata pembaca.$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$$Siswa memahami pengertian sudut$$, $$Siswa dapat menyebutkan jenis-jenis sudut$$, $$Siswa dapat mengukur sudut sederhana dengan busur derajat$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Sudut?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Sudut adalah daerah yang dibentuk oleh dua garis yang bertemu di satu titik. Titik bertemunya disebut titik sudut, sedangkan dua garisnya disebut kaki sudut. Besar sudut diukur dalam satuan derajat (°). Contoh sudut ada di mana-mana: sudut meja, sudut buku, dan jarum jam!$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Jenis-Jenis Sudut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Sudut lancip — besarnya kurang dari 90°, contoh: 30°, 45°, 60°$$, $$Sudut siku-siku — besarnya tepat 90°, seperti sudut buku dan pintu$$, $$Sudut tumpul — besarnya lebih dari 90° tetapi kurang dari 180°, contoh: 100°, 120°$$, $$Sudut lurus — besarnya tepat 180°, seperti garis lurus$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Cara Mengukur Sudut dengan Busur$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Letakkan titik tengah busur tepat di titik sudut$$, $$Sejajarkan salah satu kaki sudut dengan garis 0° pada busur$$, $$Lihat angka pada busur tempat kaki sudut yang lain berada — itulah besar sudutnya$$, $$Perhatikan skala dalam atau luar busur agar tidak salah baca$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh Soal Terpecahkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Contoh 1: Sudut 45° termasuk jenis apa? Jawab: 45° kurang dari 90°, jadi sudut lancip. Contoh 2: Sebuah sudut besarnya 110°. Termasuk jenis apa? Jawab: 110° lebih dari 90° dan kurang dari 180°, jadi sudut tumpul. Ingat: sudut siku-siku = 90° adalah patokan. Kalau lebih kecil dari siku-siku berarti lancip, kalau lebih besar berarti tumpul.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$1. Sebutkan tiga jenis sudut beserta besarnya masing-masing! → Lancip (< 90°), siku-siku (= 90°), tumpul (> 90° dan < 180°).$$, $$2. Sudut 90° disebut sudut ... → sudut siku-siku.$$, $$3. Sudut 135° termasuk sudut lancip, siku-siku, atau tumpul? → sudut tumpul.$$, $$4. Gambarlah sebuah sudut lancip (misalnya 50°) dan ukurlah dengan busur! → (praktik mandiri)$$, $$Cari benda-benda di rumahmu dan tebak jenis sudutnya — belajar jadi seru!$$]::text[]));
